What does this C code print?

```c
int g(int n) {
    int t = n * 2;
    return t + 1;
}

int main() {
    int t = 5;
    printf("%d", g(2) + t);
    return 0;
}
```

What does this C code print?

```c
void inc(int n) { n = n + 1; }

int main() {
    int a = 5;
    inc(a);
    printf("%d", a);
    return 0;
}
```
